import{c as a,Q as r,j as o,m as t}from"./chunks/framework.DGHXLY8X.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),i={name:"changelog.md"};function s(n,e,d,l,c,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Generated at build time from <a href="https://github.com/smazurov/videonode/blob/main/changelog.yml" target="_blank" rel="noreferrer"><code>changelog.yml</code></a>. Cross-reference <a href="https://github.com/smazurov/videonode/releases" target="_blank" rel="noreferrer">GitHub Releases</a> for download links and signed artifacts.</p><h2 id="_4-4-0" tabindex="-1">4.4.0 <a class="header-anchor" href="#_4-4-0" aria-label="Permalink to &quot;4.4.0&quot;">​</a></h2><p><em>2026-11-04</em></p><ul><li>An audio device that stalls or is unplugged no longer freezes video: videonode-sink now captures the stream&#39;s ALSA devices itself and hands ffmpeg one interleaved stream, fills gaps with silence, and picks the device back up after a replug without restarting the stream; audio.offset_ms corrects lip sync, streams with two or more audio devices start again, and the stream page, health API, and videonode_sink_* metrics show each device as live, missing, or sending no samples, with xruns and substituted silence (<a href="https://github.com/smazurov/videonode/commit/3374a6e" target="_blank" rel="noreferrer"><code>3374a6e</code></a>)</li><li>The stream page is rebuilt to match the source and composer pages: a Status card names the first problem between source and viewers, draws the pipeline from sources through the composer, encoder, and relay to viewers, and charts encoded fps, relay lag, and egress; counters that moved in the last 10 seconds (repeated, dropped, or duplicated frames, audio dropouts) show as chips under it, so short blips clear on their own. An Output card holds the RTSP and SRT URLs, the WebRTC player, encoder and audio settings, and recording, and a Viewers card lists clients across protocols with RTT and jitter (<a href="https://github.com/smazurov/videonode/commit/dd4f501" target="_blank" rel="noreferrer"><code>dd4f501</code></a>)</li><li>Track health reports relay_ms, how long the relay holds a frame from its first packet arriving from the encoder until it is written to WebRTC viewers (absent without WebRTC viewers); the stream page charts it and warns at 200 ms or more (<a href="https://github.com/smazurov/videonode/commit/dd4f501" target="_blank" rel="noreferrer"><code>dd4f501</code></a>)</li><li>WebRTC peers report round-trip time from RTCP receiver reports, as rtt_ms on each client and the videonode_webrtc_peer_rtt_ms gauge, matching what SRT consumers already report (<a href="https://github.com/smazurov/videonode/commit/3e17b13" target="_blank" rel="noreferrer"><code>3e17b13</code></a>)</li><li>Sources no longer go silently blank on GPUs that reject a dma-buf plane import: when radeonsi refuses a plane whose row pitch isn&#39;t 256-byte aligned (for example 1920-wide raw NV12 from a UVC device such as the Hollyland Lyra), the plane is uploaded from a CPU mapping instead, and the fallback is logged once (<a href="https://github.com/smazurov/videonode/commit/6a33e46" target="_blank" rel="noreferrer"><code>6a33e46</code></a>)</li><li>The stream page&#39;s Restart button is enabled as soon as a viewer starts the encoder, instead of staying greyed out while the page still showed the encoder as idle (<a href="https://github.com/smazurov/videonode/commit/627e1e3" target="_blank" rel="noreferrer"><code>627e1e3</code></a>)</li><li>On phones, detail-page actions and log controls wrap instead of running off screen, and a log message moves below its prefix instead of wrapping one character per line (<a href="https://github.com/smazurov/videonode/commit/eb1877b" target="_blank" rel="noreferrer"><code>eb1877b</code></a>)</li></ul><h2 id="_4-3-0" tabindex="-1">4.3.0 <a class="header-anchor" href="#_4-3-0" aria-label="Permalink to &quot;4.3.0&quot;">​</a></h2><p><em>2026-10-26</em></p><ul><li>Stream details now show encoder progress, frame advancement, and independent video/audio track health alongside the encoder stats; packet arrivals are distinguished from nonempty media units, silent audio remains valid activity, and stale FPS is no longer shown as current (<a href="https://github.com/smazurov/videonode/commit/b1812c4" target="_blank" rel="noreferrer"><code>b1812c4</code></a>)</li><li>Health snapshots are available through REST and the existing once-per-second SSE metrics stream, continue aging when output stops, and reset across encoder or publisher replacement; waiting, idle, stalled, packet-only, and disconnected telemetry states remain distinct (<a href="https://github.com/smazurov/videonode/commit/b1812c4" target="_blank" rel="noreferrer"><code>b1812c4</code></a>)</li><li>Media health is observation only: the initial stall threshold is five seconds, HDMI-loss behavior and threshold suitability still need hardware validation, and this release does not automatically restart encoders or suppress audio (<a href="https://github.com/smazurov/videonode/commit/b1812c4" target="_blank" rel="noreferrer"><code>b1812c4</code></a>)</li></ul><h2 id="_4-2-2" tabindex="-1">4.2.2 <a class="header-anchor" href="#_4-2-2" aria-label="Permalink to &quot;4.2.2&quot;">​</a></h2><p><em>2026-10-24</em></p><ul><li>HDMI sources no longer come up at 640x480 with garbage video after a cold boot: when the HDMI receiver reports a new input mode, the source reopens the capture device so the format and buffers match the real resolution, and it subscribes to mode-change events before reading the format so an early change can&#39;t be missed (<a href="https://github.com/smazurov/videonode/commit/fca2fa6" target="_blank" rel="noreferrer"><code>fca2fa6</code></a>)</li></ul><h2 id="_4-2-1" tabindex="-1">4.2.1 <a class="header-anchor" href="#_4-2-1" aria-label="Permalink to &quot;4.2.1&quot;">​</a></h2><p><em>2026-09-18</em></p><ul><li>SRT output now carries Opus audio: the RTSP relay depacketizes Opus into real access units instead of declaring an empty audio track in the MPEG-TS PMT, so OBS Media Source and other SRT readers no longer hang waiting for audio frames (<a href="https://github.com/smazurov/videonode/commit/ba9d503" target="_blank" rel="noreferrer"><code>ba9d503</code></a>)</li></ul><h2 id="_4-2-0" tabindex="-1">4.2.0 <a class="header-anchor" href="#_4-2-0" aria-label="Permalink to &quot;4.2.0&quot;">​</a></h2><p><em>2026-08-30</em></p><ul><li>Stream recording writes H264 or H265 video to keyframe-aligned fMP4/HLS segments without a second encode; the new recording UI supports live playback, poster frames, storyboard hover previews, filmstrip seeking, session size and duration, and start/stop/delete controls (<a href="https://github.com/smazurov/videonode/commit/485db82" target="_blank" rel="noreferrer"><code>485db82</code></a>)</li><li>Recording sessions now finalize cleanly after write failures, producer replacement, or shutdown; same-second restarts no longer overwrite earlier sessions, active storyboard images avoid stale browser caches, and reported size and duration include the final flushed segment (<a href="https://github.com/smazurov/videonode/commit/393f481" target="_blank" rel="noreferrer"><code>393f481</code></a>)</li><li>Sources can run a shell command that emits yuv4mpegpipe frames; VideoNode reads geometry and frame rate from the Y4M header, reports the detected format to dependent encoders, falls back to NO SIGNAL on EOF, and retries the command once per second (<a href="https://github.com/smazurov/videonode/commit/6e70147" target="_blank" rel="noreferrer"><code>6e70147</code></a>)</li><li>Staged source frames are exported through udmabuf before GPU import, fixing black composer slots when the source uses cached memfd-backed buffers and making import failures visible in the log (<a href="https://github.com/smazurov/videonode/commit/5d69332" target="_blank" rel="noreferrer"><code>5d69332</code></a>)</li><li>Composer inputs reconnect after a source process restarts instead of freezing on the last frame; retries are non-blocking and limited to once per second per slot (<a href="https://github.com/smazurov/videonode/commit/0784f23" target="_blank" rel="noreferrer"><code>0784f23</code></a>)</li><li>Composer output preserves red and blue correctly during BGRA-to-NV12 conversion, fixing swapped colors in canvas snapshots, SCM broadcasts, and downstream streams (<a href="https://github.com/smazurov/videonode/commit/90ec17d" target="_blank" rel="noreferrer"><code>90ec17d</code></a>)</li><li>Linux password authentication now runs through the packaged videonode-session PAM helper; the daemon and its child processes no longer inherit shadow-group access, and upgrades revoke the old membership (<a href="https://github.com/smazurov/videonode/commit/d06dbaf" target="_blank" rel="noreferrer"><code>d06dbaf</code></a>)</li><li>SSE event delivery no longer leaves 2 kHz dispatcher goroutines behind after clients disconnect, removing the measured 16 to 20 percent idle CPU load on RK3588 after the first UI connection (<a href="https://github.com/smazurov/videonode/commit/d72b7f7" target="_blank" rel="noreferrer"><code>d72b7f7</code></a>)</li><li>A composer&#39;s video coverage can be exported as an OBS alpha mask from the composer and stream pages, so the canvas layers over other scene content instead of arriving as one opaque rectangle; download a canvas-sized PNG for the Image Mask/Blend filter, or copy a browser-source URL whose player clips the live video to the same regions with no OBS plugin (<a href="https://github.com/smazurov/videonode/commit/2329b0c" target="_blank" rel="noreferrer"><code>2329b0c</code></a>)</li></ul><h2 id="_4-1-1" tabindex="-1">4.1.1 <a class="header-anchor" href="#_4-1-1" aria-label="Permalink to &quot;4.1.1&quot;">​</a></h2><p><em>2026-06-09</em></p><ul><li>SRT egress improvements for H265: subscribers joining between keyframes now get VPS/SPS/PPS prepended so the decoder starts immediately instead of stalling until the next IDR; the listener also gains tunable latency/bandwidth/idle-timeout knobs and aligns its payload to 1316 bytes (7x188) so MPEG-TS packets stay intact (<a href="https://github.com/smazurov/videonode/commit/37ff943" target="_blank" rel="noreferrer"><code>37ff943</code></a>)</li></ul><h2 id="_4-1-0" tabindex="-1">4.1.0 <a class="header-anchor" href="#_4-1-0" aria-label="Permalink to &quot;4.1.0&quot;">​</a></h2><p><em>2026-06-08</em></p><ul><li>Processes panel rebuilt on a dedicated SSE process stream — live per-process stats pushed instead of polled, with explicit process-removed events; the UI fetches once on start/reconnect, then follows pushes (<a href="https://github.com/smazurov/videonode/commit/6d32de6" target="_blank" rel="noreferrer"><code>6d32de6</code></a>)</li><li>the daemon now appears as its own self row with live CPU/RSS, the InfoBar derives its stats from the processes stream (dropping /api/system), and host GPU/MPP/NPU utilization is surfaced alongside (<a href="https://github.com/smazurov/videonode/commit/897d5fd" target="_blank" rel="noreferrer"><code>897d5fd</code></a>)</li><li>source capture hardened — zero-copy dma-heap DMABUF capture, a libplacebo CSC fallback when RGA can&#39;t convert NV24, 64B NV12 stride padding, and steadier behavior through signal loss and HDMI link flaps; the v1-&gt;v2 config migration and migrate-config command are gone, so streams.toml must already be version 2 (<a href="https://github.com/smazurov/videonode/commit/820265a" target="_blank" rel="noreferrer"><code>820265a</code></a>)</li><li>smaller operational fixes: auth falls back to Basic when /etc/shadow is unreadable, WHEP DELETE is idempotent for an already-closed peer, and an opt-in net/http/pprof debug server for live profiling (<a href="https://github.com/smazurov/videonode/commit/519fcb9" target="_blank" rel="noreferrer"><code>519fcb9</code></a>)</li></ul><h2 id="_4-0-0" tabindex="-1">4.0.0 <a class="header-anchor" href="#_4-0-0" aria-label="Permalink to &quot;4.0.0&quot;">​</a></h2><p><em>2026-06-03</em></p><ul><li>new pipeline architecture: sources, composers, and streams are three independent top-level entities wired by explicit upstream refs, governed by a single pipeline master switch, with encoders that spawn lazily on the first reader and stop after the last (<a href="https://github.com/smazurov/videonode/commit/b22080f" target="_blank" rel="noreferrer"><code>b22080f</code></a>)</li><li>native RK3588 media pipeline: videonode-source/composer/sink processes move NV12 dma-bufs zero-copy over SCM_RIGHTS, with a libplacebo GPU compositor and an NV12-end-to-end path carrying colorimetry through to the encoder (<a href="https://github.com/smazurov/videonode/commit/1a42a4d" target="_blank" rel="noreferrer"><code>1a42a4d</code></a>)</li><li>GPU composer with a live layout editor: multi-source compositing onto a canvas, a Region/Content model with per-slot rotation, crop, pan/zoom and fit, per-input perspective effects, configurable background, and edits that apply without restarting the pipeline — plus composer config TOML export/import (<a href="https://github.com/smazurov/videonode/commit/c1a4d04" target="_blank" rel="noreferrer"><code>c1a4d04</code></a>)</li><li>WebRTC playback via a WHEP egress endpoint with H265, fanning out alongside SRT and RTSP from the built-in local relay (<a href="https://github.com/smazurov/videonode/commit/f412934" target="_blank" rel="noreferrer"><code>f412934</code></a>)</li><li>RK3588 hardware acceleration end to end: hardware MJPEG decode through MPP, rkmpp encoders ingesting BGRA/RGB directly, and an S32_LE-capable audio capture path for the on-board ADC (<a href="https://github.com/smazurov/videonode/commit/cea24f4" target="_blank" rel="noreferrer"><code>cea24f4</code></a>)</li><li>rebuilt operational web UI on a single typed SSE entity stream: live pipeline/source/stream stats and sparklines, per-entity log panels, consumer counts and client IPs, process restart controls, an embedded WHEP player, and dead-rig detection (<a href="https://github.com/smazurov/videonode/commit/22fbdd1" target="_blank" rel="noreferrer"><code>22fbdd1</code></a>)</li><li>unified .deb packaging with a GitHub Pages APT repo, shadow-group-gated auth with postinst enrollment, and service auto-start on install — replacing goreleaser, the in-app self-update service, and install.sh (<a href="https://github.com/smazurov/videonode/commit/55a842b" target="_blank" rel="noreferrer"><code>55a842b</code></a>)</li><li>VitePress documentation site with Mermaid diagrams, search, and versioned navigation (<a href="https://github.com/smazurov/videonode/commit/cdd37c1" target="_blank" rel="noreferrer"><code>cdd37c1</code></a>)</li></ul><h2 id="_3-1-0" tabindex="-1">3.1.0 <a class="header-anchor" href="#_3-1-0" aria-label="Permalink to &quot;3.1.0&quot;">​</a></h2><p><em>2026-05-18</em></p><ul><li>feat: v3.1.0 release (<a href="https://github.com/smazurov/videonode/commit/676bf30" target="_blank" rel="noreferrer"><code>676bf30</code></a>)</li></ul>',29)])])}const u=a(i,[["render",s]]);export{p as __pageData,u as default};
